{"cmd":"node <<'NODE'
const { execSync } = require('child_process');
const fs = require('fs');
function parse(s){
  const out = new Map();
  let key = null;
  for (const line of s.split(/\n/)) {
    if (!line.startsWith(' ') && line.trim().endsWith(':')) key = line.slice(0,-1);
    else if (key && line.startsWith('  version ')) { out.set(key, line.trim().replace(/^version /,'')); key = null; }
  }
  return out;
}
const old = parse(execSync('git show HEAD:yarn.lock', {encoding:'utf8', maxBuffer: 50*1024*1024}));
const cur = parse(fs.readFileSync('yarn.lock','utf8'));
const changes=[];
for (const [k,v] of cur) {
  if (old.has(k) && old.get(k)!==v) changes.push([k, old.get(k), v]);
  else if (!old.has(k)) changes.push([k, null, v]);
}
for (const [k,v] of old) if (!cur.has(k)) changes.push([k, v, null]);
changes.sort((a,b)=>a[0].localeCompare(b[0]));
console.log(changes.length);
for (const c of changes) console.log(c.join(' | '));
NODE","workdir":"/app","yield_time_ms":10000,"max_output_tokens":30000}

